ALTER TABLE transactions ADD COLUMN adjusted_rate numeric;

UPDATE transactions t
SET adjusted_rate = m.esccomprate
FROM markets m
WHERE t.mktref = m.mktregistry;

CREATE INDEX idx_transactions_anomaly_detection 
ON transactions (payamtusd, txfinishhrs, escrowhrs) 
WHERE payamtusd IS NOT NULL AND txfinishhrs IS NOT NULL AND escrowhrs IS NOT NULL;

